import os
import csv
from pathlib import Path
from decimal import Decimal

node_dir = Path(os.environ["NODE_FLOW_DIR"])
consumer_dir = Path(os.environ["CONSUMER_FLOW_DIR"])

node_path = node_dir / "20190114_node.csv"
consumer_path = consumer_dir / "20190114_consumer.csv"

def read_rows(path):
    with open(path, newline="", encoding="utf-8-sig") as f:
        return list(csv.DictReader(f))

node_rows = read_rows(node_path)
consumer_rows = read_rows(consumer_path)

def find_col(row, candidates):
    for c in candidates:
        if c in row and row[c] not in (None, ""):
            return c
    return None

node_col = None
for r in node_rows:
    node_col = find_col(r, ["计算流量", "流量", "需求", "需求量", "demand", "flow"])
    if node_col:
        break

consumer_col = None
for r in consumer_rows:
    consumer_col = find_col(r, ["消耗量", "消耗", "用量", "consumption", "consumer_flow"])
    if consumer_col:
        break

def to_dec(v):
    try:
        return Decimal(str(v).replace(",", "").strip())
    except Exception:
        return None

node_total = Decimal("0")
node_count = 0
for r in node_rows:
    if node_col:
        v = to_dec(r.get(node_col))
        if v is not None:
            node_total += v
            node_count += 1

consumer_total = Decimal("0")
consumer_count = 0
for r in consumer_rows:
    if consumer_col:
        v = to_dec(r.get(consumer_col))
        if v is not None:
            consumer_total += v
            consumer_count += 1

diff = node_total - consumer_total

print(f"node_demand_rows={node_count}")
print(f"consumer_rows={consumer_count}")
print(f"node_total={node_total}")
print(f"consumer_total={consumer_total}")
print(f"difference_node_minus_consumer={diff}")
print(f"abs_difference={abs(diff)}")

